use std::{alloc::{GlobalAlloc,Layout,System},sync::atomic::{AtomicBool,Ordering},path::PathBuf};
struct FaultAllocator;
static FAIL:AtomicBool=AtomicBool::new(false);
unsafe impl GlobalAlloc for FaultAllocator {unsafe fn alloc(&self,l:Layout)->*mut u8 {if FAIL.load(Ordering::Relaxed)&&l.size()==8650761 {return std::ptr::null_mut()} System.alloc(l)} unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)} }
#[global_allocator]static ALLOC:FaultAllocator=FaultAllocator;
fn main(){let mut args=std::env::args().skip(1);let input=PathBuf::from(args.next().unwrap());let out=PathBuf::from(args.next().unwrap());std::fs::create_dir_all(&out).unwrap();std::env::set_var("OUT_DIR",&out);let bytes=std::fs::read(&input).unwrap();let mut h=tauri_codegen::vendor::blake3_reference::Hasher::default();h.update(&bytes);let mut digest=[0u8;32];h.finalize(&mut digest);let hash:String=digest.iter().map(|b|format!("{b:02x}")).collect();println!("hash={hash}");FAIL.store(std::env::var_os("THEN_INJECT_ALLOCATION_FAILURE").is_some(),Ordering::Relaxed);let result=tauri_codegen::embedded_assets::EmbeddedAssets::new(input,&Default::default(),|_,_,_,_|Ok(()));println!("codegen_success={}",result.is_ok());if let Err(e)=result {eprintln!("{e}");std::process::exit(2)}for e in std::fs::read_dir(out.join("tauri-codegen-assets")).unwrap(){let e=e.unwrap();println!("cache={} bytes={}",e.file_name().to_string_lossy(),e.metadata().unwrap().len())}}
